import{_ as t,o as n,c as r,a2 as a}from"./chunks/framework.Bg-Zxr5O.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Statistical-Functions.md","filePath":"manual-zh/Statistical-Functions.md","lastUpdated":1785684581000}'),o={name:"manual-zh/Statistical-Functions.md"};function p(m,e,s,_,u,c){return n(),r("div",null,[...e[0]||(e[0]=[a('<h4 id="_7-7-6-统计函数" tabindex="-1">7.7.6 统计函数 <a class="header-anchor" href="#_7-7-6-统计函数" aria-label="Permalink to &quot;7.7.6 统计函数&quot;">​</a></h4><p>统计函数用于计算一组值的描述性统计量。部分统计量可在数值或字符串值上计算；其余只能用于数值值。其结果与参数的类型相同。当前个案的加权因子（见 <a href="./WEIGHT">WEIGHT</a>）对统计函数没有影响。</p><p>这些函数的参数列表可以使用 <code>var1 TO var2</code> 语法包含整个变量范围。</p><p>与大多数函数不同，即使部分参数为缺失值，统计函数仍可返回非缺失值。默认情况下，大多数统计函数只需 1 个非缺失值即可返回非缺失结果，但 <code>CFVAR</code>、<code>SD</code> 和 <code>VARIANCE</code> 需要 2 个。可以通过在函数名后追加一个点号及有效参数的最小数量来提高（但不能降低）该默认值。例如，<code>MEAN.3(X, Y, Z)</code> 仅在 ‘X’、‘Y’、‘Z’ 全部有效时才返回非缺失值。</p><p>函数：__<strong>CFVAR</strong> <em>( number, number[, …])</em></p><p>返回 number 各值的变异系数。（变异系数为标准差除以均值。）</p><p>函数：__<strong>MAX</strong> <em>( value, value[, …])</em></p><p>返回最大值。这些值可以是数值或字符串。</p><p>函数：__<strong>MEAN</strong> <em>( number, number[, …])</em></p><p>返回 number 各值的均值。</p><p>函数：__<strong>MEDIAN</strong> <em>( number, number[, …])</em></p><p>返回 number 各值的中位数。若非缺失参数个数为偶数，则取中间两个值的均值。</p><p>函数：__<strong>MIN</strong> <em>( value, value[, …])</em></p><p>返回最小值。这些值可以是数值或字符串。</p><p>函数：__<strong>SD</strong> <em>( number, number[, …])</em></p><p>返回 number 各值的标准差。</p><p>函数：__<strong>SUM</strong> <em>( number, number[, …])</em></p><p>返回 number 各值的和。</p><p>函数：__<strong>VARIANCE</strong> <em>( number, number[, …])</em></p><p>返回 number 各值的方差。</p>',20)])])}const l=t(o,[["render",p]]);export{d as __pageData,l as default};
